window.App=(()=>{
 const {e,icon,button,badge,field,input,select,link,empty}=UI;
 const ui={route:(location.hash||'#home').slice(1),navCollapsed:Cousins.db.navCollapsed||false,subCollapsed:Cousins.db.subCollapsed||{},previewFile:'',testMode:'mock',testing:false};
 const nav=[['home','Home','home'],['presets','Acquisition presets','grid'],['devices','Devices','device'],['analytics','Analytics','chart'],['collections','Collections','folder']];
 let lastRoute='',focusReturn=null;
 function section(){const root=ui.route.split('/')[0];return ['editor','start'].includes(root)?'presets':['device','test','register'].includes(root)?'devices':['collection','active'].includes(root)?'collections':root==='logs'?(Diagnostics.state.returnRoute==='settings'?'settings':'collections'):root;}
 function presetSidebar(){const id=ui.route.split('/')[1];if(ui.subCollapsed.presets)return `<aside class="page-sidebar collapsed"><button class="reopen-sidebar" data-action="toggle-sub" aria-label="Expand presets">${icon('panel')}</button></aside>`;return `<aside class="page-sidebar"><div class="subhead"><h2>Presets</h2>${button('Collapse presets','toggle-sub',{icon:'left',iconOnly:true})}</div><div class="subsearch">${icon('search')}<input aria-label="Filter presets" type="search" data-subfilter placeholder="Find a preset"></div><div class="subitems">${Cousins.db.presets.map(p=>`<a href="#editor/${p.id}" class="subitem ${p.id===id?'selected':''}" data-subsearch="${e((p.name+' '+p.family).toLowerCase())}"><span class="od-field od-fill"><strong class="od-clamp-2">${e(p.name)}</strong><span class="submeta">${e(p.profile||p.family)} · ${p.views.length} views</span></span><span class="revision">r${p.revision}</span></a>`).join('')}</div><div class="sidebar-bottom">${link('New preset','editor/new','btn quiet','plus')}</div></aside>`;}
 function shell(){return `<div class="app-shell"><nav class="mainnav" aria-label="Main navigation"><a href="#home" class="brand" aria-label="Cousins home"><img src="assets/cousins-logo.png" width="1254" height="1254" alt=""><span>Cousins</span></a><div class="nav-items">${nav.map(([route,name,ico])=>`<a href="#${route}" class="nav-item" data-nav="${route}" title="${name}">${icon(ico)}<span>${name}</span></a>`).join('')}</div><div class="nav-bottom"><a href="#settings" class="nav-item" data-nav="settings" title="Settings">${icon('gear')}<span>Settings</span></a><button class="nav-item" data-action="toggle-nav" aria-label="Collapse main navigation">${icon('left')}<span>Collapse</span></button></div></nav><main id="main" tabindex="-1"><div id="route-content"></div><div id="analytics-host" hidden></div></main></div>`;}
 function theme(){document.documentElement.dataset.theme=Cousins.db.appearance==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):Cousins.db.appearance;}
 function render(){const scroll=document.querySelector('#main')?.scrollTop||0;Runtime.unmount();Charts.dispose();theme();const [route,id,sub]=ui.route.split('/');let content;switch(route){case'home':content=Pages.home();break;case'presets':content=Pages.presetList();break;case'editor':Editor.open(id);content=Editor.render();break;case'start':content=Pages.start(Cousins.getPreset(id));break;case'active':content=Runtime.render(Cousins.getCollection(id));break;case'devices':content=Pages.devices();break;case'device':content=Pages.device(Cousins.getDevice(id));break;case'register':content=Pages.register();break;case'test':content=Pages.test(Cousins.getDevice(id));break;case'collections':content=Pages.collections();break;case'collection':content=Pages.collection(Cousins.getCollection(id),sub==='export');break;case'analytics':content='';break;case'logs':content=Diagnostics.renderPage();break;case'settings':content=Pages.settings();break;default:content=empty('Page not found',link('Home','home','btn'));}if(!document.getElementById('main'))document.getElementById('app').innerHTML=shell();
 const ordinary=document.getElementById('route-content'),analytics=document.getElementById('analytics-host');ordinary.hidden=route==='analytics';analytics.hidden=route!=='analytics';if(route==='analytics'){if(!analytics.children.length)analytics.innerHTML=Analytics.render();}else ordinary.innerHTML=content;
 const key=section();document.querySelector('.app-shell').classList.toggle('nav-collapsed',ui.navCollapsed);document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===key;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const toggle=document.querySelector('[data-action="toggle-nav"]');toggle.innerHTML=icon(ui.navCollapsed?'right':'left')+'<span>Collapse</span>';toggle.setAttribute('aria-label',ui.navCollapsed?'Expand main navigation':'Collapse main navigation');document.querySelector('#main').scrollTop=lastRoute===ui.route?scroll:0;lastRoute=ui.route;if(route==='editor')Editor.mount();if(route==='analytics')Analytics.mount();Analytics.syncTheme();if(route==='home')Pages.mountHome();if(route!=='analytics'){const run=route==='active'?Runtime.active():null,r=run?Runtime.bounds(run):null;Charts.mount(document.getElementById('route-content'),r?r.endSeconds:120,r?{start:r.startSeconds,end:r.endSeconds}:null);}if(route==='active')Runtime.mount();if(route==='collection'&&sub==='export')RecordingData.openCsv(id);}
 function navigate(to,sync=true){ui.route=to.replace(/^#/,'')||'home';ui.previewFile='';if(ui.route.startsWith('active/'))Diagnostics.state.scope=ui.route.split('/')[1];if(sync){try{history.pushState(null,'','#'+ui.route);}catch{}}render();document.querySelector('#main')?.focus({preventScroll:true});}
 function toast(message){if(/unavailable|enter |invalid|reconnect/i.test(message))Capture.add({severity:'warning',source:'Application',eventType:'application.feedback',message,collectionId:ui.route.startsWith('active/')?ui.route.split('/')[1]:null});const t=document.getElementById('toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,4000);}
 function confirm(title,text,label,callback){focusReturn=document.activeElement;const dialog=document.getElementById('dialog');dialog.innerHTML=`<form method="dialog"><header><h2>${e(title)}</h2><button class="btn icon-only quiet" value="cancel" aria-label="Close">${icon('close')}</button></header><p>${e(text)}</p><footer><button class="btn" value="cancel">Cancel</button><button class="btn danger danger-solid" value="confirm">${e(label)}</button></footer></form>`;dialog.onclose=()=>{if(dialog.returnValue==='confirm')callback();focusReturn?.isConnected&&focusReturn.focus();};dialog.showModal();}
 function inlineName(label,value,onSave){const host=document.querySelector('.page-header');const old=document.getElementById('inline-name');old?.remove();const form=document.createElement('form');form.id='inline-name';form.className='inline-name';form.innerHTML=`<label>${e(label)}<input name="name" value="${e(value)}" required maxlength="100"></label><button class="btn primary" type="submit">Save</button><button class="btn" type="button" data-cancel-name>Cancel</button>`;host.after(form);form.querySelector('[data-cancel-name]').onclick=()=>form.remove();form.onsubmit=ev=>{ev.preventDefault();const name=form.elements.name.value.trim();if(name){onSave(name);form.remove();}};form.elements.name.focus();}
 function activeComponents(){if(ui.route.startsWith('editor/'))return Editor.view().components;if(ui.route.startsWith('active/')){const run=Runtime.active();return (run.preset.views.find(v=>v.id===run.view)||run.preset.views[0]).components;}return [];}
 document.addEventListener('click',ev=>{
 const anchor=ev.target.closest('a[href^="#"]');if(anchor&&!ev.metaKey&&!ev.ctrlKey&&!ev.shiftKey){ev.preventDefault();const target=anchor.getAttribute('href').slice(1),exportMatch=target.match(/^collection\/([^/]+)\/export$/);if(exportMatch){RecordingData.openCsv(exportMatch[1]);return;}navigate(target);return;}
 const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;
 if(action==='toggle-nav'){ui.navCollapsed=!ui.navCollapsed;Cousins.db.navCollapsed=ui.navCollapsed;Cousins.save();if(ui.route==='analytics'){document.querySelector('.app-shell').classList.toggle('nav-collapsed',ui.navCollapsed);el.innerHTML=icon(ui.navCollapsed?'right':'left')+'<span>Collapse</span>';el.setAttribute('aria-label',ui.navCollapsed?'Expand main navigation':'Collapse main navigation');}else render();return;}
 if(action==='toggle-sub'){const key=section();ui.subCollapsed[key]=!ui.subCollapsed[key];Cousins.db.subCollapsed=ui.subCollapsed;Cousins.save();render();return;}
 if(action==='download-parquet'){RecordingData.parquet(ui.route.split('/')[1],id,el);return;}if(action==='close-csv'){RecordingData.closeCsv();return;}
 if(Diagnostics.action(action,id,el))return;
 if(ui.route.startsWith('editor/')&&Editor.action(action,id,el))return;
 if(ui.route.startsWith('active/')&&Runtime.action(action,id,el))return;
 if(ui.route.startsWith('analytics')&&Analytics.action(action,id))return;
 if(action==='duplicate-preset'){const p=Cousins.clone(Cousins.getPreset(id));p.id='preset-'+Date.now();p.name+=' copy';p.revision=1;Cousins.db.presets.unshift(p);Cousins.save();navigate('editor/'+p.id);}
 else if(action==='appearance'){Cousins.db.appearance=id;Cousins.save();render();}
 else if(action==='version'){const id=document.getElementById('target-version')?.value;if(!id||id===Cousins.db.version)return;confirm('Change version?',`Switch the displayed version from ${Cousins.db.version} to ${id}. This prototype does not install software.`,'Change version',()=>{Cousins.db.version=id;Cousins.save();render();});}
 else if(action==='rename-collection'){const c=Cousins.getCollection(id);inlineName('Collection name',c.name,name=>{c.name=name;Cousins.save();render();});}
 else if(action==='delete-collection'){const c=Cousins.getCollection(id);confirm('Delete collection?',`Delete “${c.name}” and its ${c.files.length} recording files? This cannot be undone.`,'Delete collection',()=>{Cousins.db.collections=Cousins.db.collections.filter(x=>x.id!==id);Cousins.save();navigate('collections');});}
 else if(action==='delete-derived'){const c=Cousins.getCollection(id);confirm('Delete derived results?',`Remove derived results from “${c.name}”. Keep all raw recordings.`,'Delete results',()=>{c.derived=false;Cousins.save();render();});}
 else if(action==='preview-file'){ui.previewFile=id;render();}
 else if(action==='test-run'){const param=document.getElementById('test-parameter');if(!param.checkValidity()){param.reportValidity();return;}ui.testing=!ui.testing;render();}
 else if(action==='cal-add'){const c=Layout.find(activeComponents(),id)?.component;if(c){if(ui.route.startsWith('editor'))Editor.checkpoint();c.rows.push(['','']);Cousins.save();render();}}
 else if(action==='cal-remove'){const [cid,index]=id.split(':');const c=Layout.find(activeComponents(),cid)?.component;if(c){if(ui.route.startsWith('editor'))Editor.checkpoint();c.rows.splice(Number(index),1);Cousins.save();render();}}
 });
 document.addEventListener('input',ev=>{const el=ev.target;if(el.hasAttribute('data-filter'))document.querySelectorAll(`[data-filter-kind="${el.dataset.filter}"]`).forEach(row=>row.hidden=!row.dataset.search.includes(el.value.toLowerCase()));if(el.hasAttribute('data-subfilter'))document.querySelectorAll('[data-subsearch]').forEach(row=>row.hidden=!row.dataset.subsearch.includes(el.value.toLowerCase()));if(el.id==='config-code'){document.getElementById('code-highlight').innerHTML=Pages.highlight(el.value);}if(el.hasAttribute('data-parameter')&&ui.route.startsWith('active/')){const state=Runtime.active().deviceStates[el.dataset.parameter];if(state){state.draft=Number(el.value);const note=el.closest('.control-body')?.querySelector('.applied-line>span');if(note)note.innerHTML='Pending <strong>'+UI.e(el.value)+' '+UI.e(Cousins.getDevice(el.dataset.parameter)?.unit)+'</strong> · applied '+UI.e(state.applied);}}if(el.hasAttribute('data-replay-position'))Runtime.seek(el.value);});
 document.addEventListener('invalid',ev=>{Capture.add({severity:'warning',source:'Validation',eventType:'form.invalid',message:ev.target.validationMessage,details:{field:ev.target.name||ev.target.id}});},true);
 document.addEventListener('scroll',ev=>{if(ev.target.id==='config-code'){const pre=document.getElementById('code-highlight');pre.scrollTop=ev.target.scrollTop;pre.scrollLeft=ev.target.scrollLeft;}},true);
 document.addEventListener('change',ev=>{const el=ev.target;if(ui.route.startsWith('editor/')&&Editor.change(el))return;
 if(el.hasAttribute('data-analytics-tool'))Analytics.setTool(el.value);if(el.id==='target-version')Pages.versionSelection(el.value);
 if(el.hasAttribute('data-test-mode')){ui.testMode=el.value;ui.testing=false;render();}
 if(el.id==='offline-package')toast(el.files[0]?'Selected '+el.files[0].name+'. Installation is unavailable in this prototype.':'No package selected.');
 if(el.hasAttribute('data-replay-speed'))Runtime.speed(el.value);
 if(el.hasAttribute('data-value-field')){const c=Layout.find(activeComponents(),el.dataset.component)?.component,f=c?.fields.find(f=>f.id===el.dataset.valueField);if(f){if(!el.checkValidity()){el.reportValidity();return;}if(ui.route.startsWith('editor'))Editor.checkpoint();f.value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;Cousins.save();}}
 if(el.hasAttribute('data-cal')){const c=Layout.find(activeComponents(),el.dataset.cal)?.component;if(c){if(ui.route.startsWith('editor'))Editor.checkpoint();c.rows[Number(el.dataset.row)][Number(el.dataset.col)]=el.value;const refs=c.rows.map(r=>r[0]);el.setCustomValidity(refs.filter(v=>v===el.value).length>1&&el.dataset.col==='0'?'Reference values must be distinct.':'');if(!el.checkValidity())el.reportValidity();Cousins.save();}}
 if(el.name==='format'&&ui.route==='register'){const ta=document.getElementById('config-code');ta.value=el.value==='toml'?'[device]\nname = "Temperature probe"\nprotocol = "mock"\n\n[[channels]]\nid = "temperature"\nunit = "°C"\nshape = "scalar"\n':'device:\n  name: Temperature probe\n  protocol: mock\nchannels:\n  - id: temperature\n    unit: °C\n    shape: scalar\n';document.getElementById('code-highlight').innerHTML=Pages.highlight(ta.value);}
 });
 document.addEventListener('submit',ev=>{const form=ev.target;if(!['start-form','register-form','export-form','analytics-connection'].includes(form.id))return;ev.preventDefault();const data=new FormData(form);
 if(form.id==='start-form'){const p=Cousins.clone(Cousins.getPreset(form.dataset.preset));p.policy=data.get('policy');Runtime.start(data.get('name').trim(),p);}
 if(form.id==='analytics-connection')Analytics.connect(form);
 if(form.id==='register-form'){
  const name=data.get('name').trim(),config=data.get('config'),format=data.get('format'),protocol=data.get('protocol');const error=document.getElementById('register-error');if(!name){error.textContent='Enter a device name.';return;}if(protocol==='driver'&&!data.get('driver').trim()){error.textContent='Enter the driver or sidecar path.';return;}
  if(format==='yaml'&&!/device\s*:/.test(config)||format==='toml'&&!/\[device\]/.test(config)){error.textContent='Add the device section to the configuration.';return;}
  const ids=[...config.matchAll(/\bid\s*[:=]\s*["']?([\w-]+)/g)].map(m=>m[1]),units=[...config.matchAll(/\bunit\s*[:=]\s*["']?([^\n"']+)/g)].map(m=>m[1].trim());const d={id:'device-'+Date.now(),name,kind:data.get('kind'),status:'Ready',definition:name.toLowerCase().replace(/\W+/g,'-')+'.'+format,configuration:config,driver:data.get('driver'),protocol,channels:ids.map((id,i)=>({id,name:id.replace(/[-_]/g,' '),unit:units[i]||'',shape:'Scalar time series'})),commands:data.get('kind')==='Control'?['Enable','Disable']:['Start','Stop'],parameter:'Sample interval',unit:'ms',min:10,max:1000,step:10,applied:100};Cousins.db.devices.push(d);Cousins.save();navigate('device/'+d.id);toast('Device registered for interface testing.');
 }
 if(form.id==='export-form')RecordingData.csv(form);
 });
 window.addEventListener('hashchange',()=>navigate(location.hash,false));window.addEventListener('popstate',()=>navigate(location.hash,false));window.addEventListener('beforeunload',ev=>{if(Editor.state?.dirty){ev.preventDefault();ev.returnValue='';}});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(Cousins.db.appearance==='system')render();});
 return {ui,render,navigate,toast,confirm,inlineName,presetSidebar};
})();
App.render();
